 * Performance: On-demand rendering — only renders when user interacts or camera animates
 */
import * as THREE from 'https://esm.sh/three@0.160.0'
import { OrbitControls } from 'https://esm.sh/three@0.160.0/examples/jsm/controls/OrbitControls.js'

interface NodeData {
 table: string
 label: string
 count: number
 health: string
 category: string
 domain: string
 domainLabel: string
 populated: boolean
 relationships?: string[]
}

interface SceneNode {
 mesh: THREE.Mesh
 label: THREE.Sprite
 countLabel: THREE.Sprite
 data: NodeData
 platformIndex: number
}

interface Relationship {
 from: string
 to: string
 label: string
}

export interface SceneState {
 render: (selectedTable: string | null) => void
 hitTest: (mx: number, my: number) => NodeData | null
 getRelatedTables: (table: string) => string[]
 dispose: () => void
 resize: (width: number, height: number) => void
 focusNode: (table: string | null) => void
}

// CSDM layer colors
const LAYER_COLORS: { main: number; emissive: number; platform: number; text: string }[] = [
 { main: 0x2979ff, emissive: 0x1a4fc0, platform: 0x0f2854, text: '#82b1ff' },
 { main: 0xaa00ff, emissive: 0x7b00b8, platform: 0x2d1152, text: '#d580ff' },
 { main: 0x00bcd4, emissive: 0x008a9a, platform: 0x0a3038, text: '#80deea' },
 { main: 0xff9100, emissive: 0xb86800, platform: 0x3d2000, text: '#ffd180' },
 { main: 0x00e676, emissive: 0x00a854, platform: 0x1a3d1a, text: '#b9f6ca' },
]

const HEALTH_COLORS: Record<string, { main: number; emissive: number; glow: string }> = {
 good: { main: 0x00e676, emissive: 0x00a854, glow: '#00e676' },
 low: { main: 0xffab00, emissive: 0xb87800, glow: '#ffab00' },
 empty: { main: 0xff5252, emissive: 0xb83030, glow: '#ff5252' },
}

// Full CSDM 5.0 relationship map
const CSDM_RELATIONSHIPS: Relationship[] = [
 { from: 'cmdb_ci_appl', to: 'cmdb_ci_server', label: 'Runs on' },
 { from: 'cmdb_ci_appl', to: 'cmdb_ci_database_instance', label: 'Uses' },
 { from: 'cmdb_ci_service_auto', to: 'cmdb_ci_appl', label: 'Depends on' },
 { from: 'cmdb_ci_service', to: 'cmdb_ci_service_auto', label: 'Contains' },
 { from: 'cmdb_ci_service', to: 'service_offering', label: 'Provides' },
 { from: 'cmdb_ci_business_app', to: 'cmdb_ci_appl', label: 'Implemented by' },
 { from: 'sc_cat_item', to: 'service_offering', label: 'Fulfills' },
 { from: 'incident', to: 'cmdb_ci_service', label: 'Affects' },
 { from: 'change_request', to: 'cmdb_ci_appl', label: 'Changes' },
 { from: 'cmdb_ci_database_instance', to: 'cmdb_ci_server', label: 'Hosted on' },
 { from: 'cmdb_ci_vm_instance', to: 'cmdb_ci_server', label: 'Virtualized by' },
 { from: 'cmdb_ci_server', to: 'cmn_location', label: 'Located at' },
 { from: 'cmdb_ci_server', to: 'core_company', label: 'Owned by' },
 { from: 'cmdb_ci_computer', to: 'cmn_location', label: 'Located at' },
 { from: 'cmdb_ci_computer', to: 'cmn_department', label: 'Used by' },
 { from: 'cmdb_ci_network_gear', to: 'cmn_location', label: 'Located at' },
 { from: 'cmdb_ci_service_technical', to: 'cmdb_ci_service_auto', label: 'Groups' },
 { from: 'cmdb_software_instance', to: 'cmdb_ci_computer', label: 'Installed on' },
 { from: 'sc_request', to: 'sc_cat_item', label: 'Requests' },
 { from: 'service_offering', to: 'cmdb_ci_service', label: 'Offered by' },
]

const REL_COLORS: Record<string, number> = {
 'Runs on': 0x00e5ff,
 'Depends on': 0xff9100,
 Contains: 0x76ff03,
 Provides: 0xe040fb,
 'Implemented by': 0xffea00,
 Fulfills: 0x69f0ae,
 Affects: 0xff5252,
 Changes: 0xffd740,
 'Hosted on': 0x40c4ff,
 Uses: 0xb388ff,
 'Virtualized by': 0x18ffff,
 'Located at': 0x64ffda,
 'Owned by': 0xff80ab,
 'Used by': 0xccff90,
 Groups: 0x84ffff,
 'Installed on': 0xa7ffeb,
 Requests: 0xffe57f,
 'Offered by': 0xea80fc,
}

function createTextSprite(text: string, color: string, fontSize: number = 48): THREE.Sprite {
 const canvas = document.createElement('canvas')
 const ctx = canvas.getContext('2d')!
 canvas.width = 512
 canvas.height = 128
 ctx.clearRect(0, 0, canvas.width, canvas.height)
 ctx.font = `bold ${fontSize}px -apple-system, BlinkMacSystemFont, sans-serif`
 ctx.textAlign = 'center'
 ctx.textBaseline = 'middle'
 ctx.fillStyle = color
 ctx.fillText(text.length > 18 ? text.substring(0, 17) + '…' : text, 256, 64)

 const texture = new THREE.CanvasTexture(canvas)
 texture.needsUpdate = true
 const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false })
 const sprite = new THREE.Sprite(material)
 sprite.scale.set(2.5, 0.625, 1)
 return sprite
}

export function buildScene(container: HTMLElement, data: any): SceneState {
 const domains = data?.population?.domains
 if (!domains) {
 return {
 render: () => {},
 hitTest: () => null,
 getRelatedTables: () => [],
 dispose: () => {},
 resize: () => {},
 focusNode: () => {},
 }
 }

 // Scene setup
 const scene = new THREE.Scene()
 scene.background = new THREE.Color(0x060a18)

 // Add subtle fog for depth
 scene.fog = new THREE.Fog(0x060a18, 30, 80)

 // Camera
 const width = container.clientWidth
 const height = container.clientHeight
 const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 200)
 camera.position.set(12, 14, 18)
 camera.lookAt(0, 4, 0)

 // Renderer
 const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false })
 renderer.setSize(width, height)
 renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
 renderer.shadowMap.enabled = true
 renderer.shadowMap.type = THREE.PCFSoftShadowMap
 container.appendChild(renderer.domElement)

 // OrbitControls for 360-degree rotation + zoom
 const controls = new OrbitControls(camera, renderer.domElement)
 ;(controls as any).zoomSpeed = 0.8
 controls.enableDamping = true
 controls.dampingFactor = 0.12
 ;(controls as any).zoomToCursor = true
 controls.enableZoom = true
 controls.minDistance = 3
 controls.maxDistance = 50
 ;(controls as any).rotateSpeed = 0.6
 ;(controls as any).panSpeed = 0.8
 controls.target.set(0, 4, 0)
 controls.enablePan = true
 controls.autoRotate = false
 controls.update()

 // Lighting
 const ambientLight = new THREE.AmbientLight(0x404060, 0.6)
 scene.add(ambientLight)

 const dirLight = new THREE.DirectionalLight(0xffffff, 0.8)
 dirLight.position.set(10, 20, 10)
 dirLight.castShadow = true
 dirLight.shadow.mapSize.width = 2048
 dirLight.shadow.mapSize.height = 2048
 scene.add(dirLight)

 const pointLight1 = new THREE.PointLight(0x4488ff, 0.5, 50)
 pointLight1.position.set(-8, 12, 8)
 scene.add(pointLight1)

 const pointLight2 = new THREE.PointLight(0x00e676, 0.3, 40)
 pointLight2.position.set(8, 6, -8)
 scene.add(pointLight2)

 // Grid helper for ground reference
 const gridHelper = new THREE.GridHelper(30, 30, 0x1a2550, 0x0e1428)
 gridHelper.position.y = -0.5
 scene.add(gridHelper)

 // Camera animation state
 const DEFAULT_CAMERA_POS = new THREE.Vector3(12, 14, 18)
 const DEFAULT_TARGET = new THREE.Vector3(0, 4, 0)
 const FOCUS_DISTANCE = 7
 const CAMERA_LERP_SPEED = 0.07
 let cameraAnimTarget = DEFAULT_TARGET.clone()
 let cameraAnimPos = DEFAULT_CAMERA_POS.clone()
 let isAnimating = false

 // Build 3D nodes
 const sceneNodes: SceneNode[] = []
 const nodeGroup = new THREE.Group()
 const platformGroup = new THREE.Group()
 const relationshipGroup = new THREE.Group()
 scene.add(platformGroup)
 scene.add(nodeGroup)
 scene.add(relationshipGroup)

 const domainKeys = Object.keys(domains)
 const LAYER_HEIGHT = 3.0 // spacing between layers
 const NODE_SIZE = 1.0

 domainKeys.forEach((key, layerIdx) => {
 const domain = domains[key]
 const classes = domain.classes || []
 if (classes.length === 0) return

 const layerColor = LAYER_COLORS[layerIdx] || LAYER_COLORS[0]
 const yPos = layerIdx * LAYER_HEIGHT

 // Platform (translucent disc/box for each layer)
 const cols = Math.min(classes.length, 5)
 const rows = Math.ceil(classes.length / cols)
 const platformW = cols * 2.8 + 2
 const platformD = rows * 2.2 + 2
 const platformGeom = new THREE.BoxGeometry(platformW, 0.15, platformD)
 const platformMat = new THREE.MeshPhongMaterial({
 color: layerColor.platform,
 transparent: true,
 opacity: 0.4,
 emissive: layerColor.emissive,
 emissiveIntensity: 0.05,
 side: THREE.DoubleSide,
 })
 const platform = new THREE.Mesh(platformGeom, platformMat)
 platform.position.set(0, yPos - 0.3, 0)
 platform.receiveShadow = true
 platformGroup.add(platform)

 // Platform edge wireframe
 const edgeGeom = new THREE.EdgesGeometry(platformGeom)
 const edgeMat = new THREE.LineBasicMaterial({ color: layerColor.main, transparent: true, opacity: 0.6 })
 const edges = new THREE.LineSegments(edgeGeom, edgeMat)
 edges.position.copy(platform.position)
 platformGroup.add(edges)

 // Layer label
 const layerLabel = createTextSprite(domain.label, layerColor.text, 40)
 layerLabel.position.set(-platformW / 2 - 1.5, yPos + 0.5, 0)
 platformGroup.add(layerLabel)

 // Create nodes
 classes.forEach((cls: any, i: number) => {
 const col = i % cols
 const row = Math.floor(i / cols)
 const xPos = (col - (cols - 1) / 2) * 2.8
 const zPos = (row - (rows - 1) / 2) * 2.2

 const hc = HEALTH_COLORS[cls.health] || HEALTH_COLORS.empty

 // Node box
 const nodeGeom = new THREE.BoxGeometry(NODE_SIZE * 1.8, NODE_SIZE * 0.8, NODE_SIZE * 1.2)
 const nodeMat = new THREE.MeshPhongMaterial({
 color: hc.main,
 emissive: hc.emissive,
 emissiveIntensity: 0.2,
 transparent: true,
 opacity: 0.9,
 shininess: 60,
 })
 const mesh = new THREE.Mesh(nodeGeom, nodeMat)
 mesh.position.set(xPos, yPos + 0.5, zPos)
 mesh.castShadow = true
 mesh.receiveShadow = true
 nodeGroup.add(mesh)

 // Wireframe outline for each node
 const wireGeom = new THREE.EdgesGeometry(nodeGeom)
 const wireMat = new THREE.LineBasicMaterial({ color: hc.main, transparent: true, opacity: 0.8 })
 const wire = new THREE.LineSegments(wireGeom, wireMat)
 wire.position.copy(mesh.position)
 nodeGroup.add(wire)

 // Name label
 const label = createTextSprite(cls.label, '#e0e6ff', 44)
 label.position.set(xPos, yPos + 1.2, zPos)
 nodeGroup.add(label)

 // Count label
 const countText = cls.count >= 0 ? `${cls.count.toLocaleString()} records` : 'N/A'
 const countLabel = createTextSprite(countText, hc.glow, 36)
 countLabel.position.set(xPos, yPos + 0.8, zPos)
 nodeGroup.add(countLabel)

 sceneNodes.push({
 mesh,
 label,
 countLabel,
 data: { ...cls, domain: key, domainLabel: domain.label },
 platformIndex: layerIdx,
 })
 })
 })

 // Build relationship lines
 const nodePositionMap = new Map<string, THREE.Vector3>()
 sceneNodes.forEach((n) => nodePositionMap.set(n.data.table, n.mesh.position.clone()))

 function buildRelationshipLines(selectedTable: string | null) {
 // Clear existing
 while (relationshipGroup.children.length > 0) {
 const child = relationshipGroup.children[0]
 relationshipGroup.remove(child)
 if ((child as any).geometry) (child as any).geometry.dispose()
 if ((child as any).material) (child as any).material.dispose()
 }

 const relatedTables = selectedTable ? getRelatedTables(selectedTable) : []
 const highlightSet = selectedTable ? new Set([selectedTable, ...relatedTables]) : null

 CSDM_RELATIONSHIPS.forEach((rel) => {
 const fromPos = nodePositionMap.get(rel.from)
 const toPos = nodePositionMap.get(rel.to)
 if (!fromPos || !toPos) return

 const isHighlighted = selectedTable && (rel.from === selectedTable || rel.to === selectedTable)
 const isVisible = !highlightSet || isHighlighted
 if (!isVisible) return

 const color = REL_COLORS[rel.label] || 0x64b5f6

 // Create curved line using QuadraticBezierCurve3
 const midPoint = new THREE.Vector3(
 (fromPos.x + toPos.x) / 2,
 Math.max(fromPos.y, toPos.y) + 1.5,
 (fromPos.z + toPos.z) / 2
 )
 const curve = new THREE.QuadraticBezierCurve3(fromPos, midPoint, toPos)
 const points = curve.getPoints(30)
 const lineGeom = new THREE.BufferGeometry().setFromPoints(points)
 const lineMat = new THREE.LineBasicMaterial({
 color: color,
 transparent: true,
 opacity: isHighlighted ? 0.9 : 0.2,
 linewidth: 1,
 })
 const line = new THREE.Line(lineGeom, lineMat)
 relationshipGroup.add(line)

 // Arrow at endpoint
 if (isHighlighted) {
 const dir = new THREE.Vector3().subVectors(toPos, midPoint).normalize()
 const arrowGeom = new THREE.ConeGeometry(0.15, 0.4, 6)
 const arrowMat = new THREE.MeshBasicMaterial({ color: color })
 const arrow = new THREE.Mesh(arrowGeom, arrowMat)
 arrow.position.copy(toPos).add(dir.multiplyScalar(-0.6))
 arrow.lookAt(toPos)
 arrow.rotateX(Math.PI / 2)
 relationshipGroup.add(arrow)
 }
 })
 }

 function getRelatedTables(table: string): string[] {
 const related = new Set<string>()
 CSDM_RELATIONSHIPS.forEach((r) => {
 if (r.from === table) related.add(r.to)
 if (r.to === table) related.add(r.from)
 })
 return Array.from(related)
 }

 // Raycaster for hit testing
 const raycaster = new THREE.Raycaster()
 const pointer = new THREE.Vector2()

 function hitTest(mx: number, my: number): NodeData | null {
 const rect = renderer.domElement.getBoundingClientRect()
 pointer.x = ((mx - rect.left) / rect.width) * 2 - 1
 pointer.y = -((my - rect.top) / rect.height) * 2 + 1
 raycaster.setFromCamera(pointer, camera)

 const meshes = sceneNodes.map((n) => n.mesh)
 const intersects = raycaster.intersectObjects(meshes, false)
 if (intersects.length > 0) {
 const hitMesh = intersects[0].object
 const node = sceneNodes.find((n) => n.mesh === hitMesh)
 if (node) {
 const rels = CSDM_RELATIONSHIPS.filter((r) => r.from === node.data.table || r.to === node.data.table)
 const relInfo = rels.map((r) => {
 if (r.from === node.data.table) return `${r.label} → ${findLabel(r.to)}`
 return `${findLabel(r.from)} → ${r.label}`
 })
 return { ...node.data, relationships: relInfo }
 }
 }
 return null
 }

 function findLabel(table: string): string {
 for (const n of sceneNodes) {
 if (n.data.table === table) return n.data.label
 }
 return table
 }

 // Render + highlight logic
 let currentSelected: string | null = null

 function render(selectedTable: string | null) {
 currentSelected = selectedTable
 const relatedTables = selectedTable ? getRelatedTables(selectedTable) : []
 const highlightSet = selectedTable ? new Set([selectedTable, ...relatedTables]) : null

 // Update node visibility/opacity
 sceneNodes.forEach((n) => {
 const mat = n.mesh.material as THREE.MeshPhongMaterial
 const isSelected = selectedTable === n.data.table
 const isRelated = highlightSet ? highlightSet.has(n.data.table) : true
 const isDimmed = highlightSet && !isRelated

 mat.opacity = isDimmed ? 0.15 : 0.9
 mat.emissiveIntensity = isSelected ? 0.6 : isRelated && highlightSet ? 0.4 : 0.2

 if (isSelected) {
 mat.emissive = new THREE.Color(0xffffff)
 } else {
 const hc = HEALTH_COLORS[n.data.health] || HEALTH_COLORS.empty
 mat.emissive = new THREE.Color(hc.emissive)
 }

 // Label visibility
 ;(n.label.material as THREE.SpriteMaterial).opacity = isDimmed ? 0.1 : 1.0
 ;(n.countLabel.material as THREE.SpriteMaterial).opacity = isDimmed ? 0.1 : 1.0
 })

 buildRelationshipLines(selectedTable)

 // Trigger a re-render after visual changes
 if (!renderLoopRunning) {
 renderOneFrame()
 }
 }

 function focusNode(table: string | null) {
 if (!table) {
 // Return to overview position
 cameraAnimTarget.copy(DEFAULT_TARGET)
 cameraAnimPos.copy(DEFAULT_CAMERA_POS)
 isAnimating = true
 startRenderLoop()
 return
 }

 const node = sceneNodes.find((n) => n.data.table === table)
 if (!node) return

 const nodePos = node.mesh.position.clone()
 cameraAnimTarget.copy(nodePos)

 // Approach from the current viewing direction at a fixed distance
 const currentDir = new THREE.Vector3()
 .subVectors(camera.position, controls.target)
 .normalize()
 cameraAnimPos.copy(nodePos).add(currentDir.multiplyScalar(FOCUS_DISTANCE))
 // Ensure we look slightly down at the node
 cameraAnimPos.y = Math.max(cameraAnimPos.y, nodePos.y + 3)

 isAnimating = true
 startRenderLoop()
 }

 // ============================================================
 // ON-DEMAND RENDERING
 // Only render when user interacts or camera is animating.
 // OrbitControls with enableDamping needs continuous update()
 // calls during and after interaction for deceleration to work.
 // ============================================================
 let animationId = 0
 let renderLoopRunning = false
 let userInteracting = false
 let dampingFrames = 0
 const DAMPING_SETTLE_FRAMES = 60 // ~1 second at 60fps for damping to fully settle

 /** Render a single frame: apply camera animation, update controls, draw */
 function renderOneFrame() {
 if (isAnimating) {
 controls.target.lerp(cameraAnimTarget, CAMERA_LERP_SPEED)
 camera.position.lerp(cameraAnimPos, CAMERA_LERP_SPEED)

 if (
 controls.target.distanceTo(cameraAnimTarget) < 0.01 &&
 camera.position.distanceTo(cameraAnimPos) < 0.01
 ) {
 controls.target.copy(cameraAnimTarget)
 camera.position.copy(cameraAnimPos)
 isAnimating = false
 }
 }

 controls.update()
 renderer.render(scene, camera)
 }

 /** Start the rAF loop if not already running */
 function startRenderLoop() {
 if (renderLoopRunning) return
 renderLoopRunning = true
 scheduleFrame()
 }

 /** Schedule the next frame in the render loop */
 function scheduleFrame() {
 animationId = requestAnimationFrame(onFrame)
 }

 /** Per-frame callback: render and decide whether to continue */
 function onFrame() {
 renderOneFrame()

 // Determine if loop should continue
 let shouldContinue = false

 if (userInteracting) {
 // Keep rendering while user is actively interacting
 shouldContinue = true
 } else if (dampingFrames > 0) {
 // After user releases, keep rendering for damping to settle
 dampingFrames--
 shouldContinue = true
 }

 if (isAnimating) {
 // Camera fly-to animation in progress
 shouldContinue = true
 }

 if (shouldContinue) {
 scheduleFrame()
 } else {
 renderLoopRunning = false
 }
 }

 // Listen for orbit control interaction events
 // Cast needed: OrbitControls extends EventDispatcher but @types/three doesn't expose addEventListener
 ;(controls as any).addEventListener('start', () => {
 userInteracting = true
 startRenderLoop()
 })

 ;(controls as any).addEventListener('end', () => {
 userInteracting = false
 dampingFrames = DAMPING_SETTLE_FRAMES
 })

 // Initial render (single frame to show the scene)
 renderOneFrame()

 function resize(width: number, height: number) {
 camera.aspect = width / height
 camera.updateProjectionMatrix()
 renderer.setSize(width, height)
 // Re-render after resize
 if (!renderLoopRunning) {
 renderOneFrame()
 }
 }

 function dispose() {
 cancelAnimationFrame(animationId)
 renderLoopRunning = false
 controls.dispose()
 renderer.dispose()
 if (renderer.domElement.parentNode) {
 renderer.domElement.parentNode.removeChild(renderer.domElement)
 }
 // Dispose geometries and materials
 scene.traverse((obj) => {
 if ((obj as any).geometry) (obj as any).geometry.dispose()
 if ((obj as any).material) {
 const mat = (obj as any).material
 if (mat.map) mat.map.dispose()
 mat.dispose()
 }
 })
 }

 return { render, hitTest, getRelatedTables, dispose, resize, focusNode }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
