export default function NodeDetail({ node }: Props) {
 if (!node) return null;

 if (node.isRisk) {
 return (
 <div className="csdm-panel">
 <h3 className="csdm-panel__title">⚠️ Risk Detail</h3>
 <div className="csdm-panel__content">
 <div className="csdm-detail-row">
 <span className="csdm-detail-label">Type:</span>
