 </div>
 <p className="csdm-detail-desc">{node.description}</p>
 <p className="csdm-detail-rec">💡 {node.recommendation}</p>
 </div>
 </div>
 );
 }

 const desc = CSDM_DESCRIPTIONS[node.table] || 'CMDB class within the CSDM framework.';

 return (
 <div className="csdm-panel">
 <h3 className="csdm-panel__title">📋 {node.label}</h3>
 <div className="csdm-panel__content">
 <p className="csdm-detail-csdm-desc">{desc}</p>

 <div className="csdm-detail-grid">
 <div className="csdm-detail-row">
 <span className="csdm-detail-label">Table:</span>
 <span className="csdm-detail-value csdm-detail-mono">{node.table}</span>
 </div>
 <div className="csdm-detail-row">
 <span className="csdm-detail-label">CSDM Layer:</span>
 <span className="csdm-detail-value">{node.domainLabel}</span>
 </div>
 <div className="csdm-detail-row">
 <span className="csdm-detail-label">Records:</span>
 <span className="csdm-detail-value">{node.count >= 0 ? node.count.toLocaleString() : 'N/A'}</span>
 </div>
 <div className="csdm-detail-row">
 <span className="csdm-detail-label">Health:</span>
 <span className={`csdm-health csdm-health--${node.health}`}>
 {node.health === 'good' ? '✓ Well Populated' : node.health === 'low' ? '⚠ Sparse' : '✗ Empty'}
 </span>
 </div>
 </div>

 {node.relationships && node.relationships.length > 0 && (
 <div className="csdm-detail-section">
 <h4 className="csdm-panel__subtitle">🔗 Connected Relationships ({node.relationships.length})</h4>
 <p className="csdm-detail-hint">These are the CSDM relationships linked to this table. They are highlighted in the 3D view.</p>
 <ul className="csdm-rel-detail-list">
 {node.relationships.map((r: string, i: number) => (
 <li key={i} className="csdm-rel-detail-item">{r}</li>
 ))}
 </ul>
 </div>
 )}

 <div className="csdm-detail-section">
 <h4 className="csdm-panel__subtitle">📌 Assessment</h4>
 <p className="csdm-detail-rec">
 {node.health === 'empty'
 ? '⚠️ No records found. This class must be populated to comply with CSDM 5.0. Consider enabling Discovery or manual CI creation.'
 : node.health === 'low'
 ? '📈 This class has few records. Verify Discovery scopes cover all relevant assets, or ensure manual intake processes are complete.'
 : '✅ Well-populated and aligned with CSDM 5.0 best practices.'}
 </p>
 </div>
 </div>
 </div>
 );
}
