 <span className="csdm-rel-stat__label">Composite</span>
 </div>
 </div>

 {/* Sub-metrics */}
 {sub && (
 <>
 <h4 className="csdm-panel__subtitle">Scoring Breakdown</h4>
 <div className="csdm-rel-submetrics">
