 <span className="csdm-rel-submetric__weight">{Math.round(m.weight * 100)}%</span>
 <span className="csdm-rel-submetric__score" style={{ color: scoreColor(m.score) }}>{m.score}%</span>
 </div>
 <div className="csdm-rel-submetric__bar">
 <div className="csdm-rel-submetric__fill" style={{ width: m.score + '%', background: scoreColor(m.score) }} />
 </div>
 <p className="csdm-rel-submetric__detail">{m.detail}</p>
 </div>
 ))}
 </div>
 </>
 )}

 {/* Per-rule breakdown */}
 {rules.length > 0 && (
 <>
 <button className="csdm-rel-toggle" onClick={() => setShowRules(!showRules)}>
 {showRules ? '▾' : '▸'} CSDM Rule Matrix ({summary?.rulesWithData || 0}/{rules.length} with data)
 </button>
 {showRules && (
 <div className="csdm-rel-rules">
 {rules.map((r: any, i: number) => (
 <div key={i} className={`csdm-rel-rule ${r.compliant > 0 ? 'csdm-rel-rule--ok' : r.parentCIs > 0 ? 'csdm-rel-rule--warn' : 'csdm-rel-rule--na'}`}>
 <div className="csdm-rel-rule__header">
 <span className="csdm-rel-rule__icon">{r.compliant > 0 ? '✓' : r.parentCIs > 0 ? '⚠' : '—'}</span>
 <span className="csdm-rel-rule__label">{r.rule}</span>
 </div>
 <div className="csdm-rel-rule__details">
 <span className="csdm-rel-rule__domain">{r.domain}</span>
 <span className="csdm-rel-rule__stat">{r.compliant}/{r.totalBetweenPair} correct type</span>
 <span className="csdm-rel-rule__stat">{r.parentCIsWithRel}/{r.parentCIs} coverage{r.coveragePct >= 0 ? ` (${r.coveragePct}%)` : ''}</span>
 </div>
 </div>
 ))}
 </div>
 )}
 </>
 )}

 {/* Type distribution (kept for reference) */}
 {(rels.typeDistribution || []).length > 0 && (
 <>
 <h4 className="csdm-panel__subtitle">Top Relationship Types</h4>
 <ul className="csdm-rel-type-list">
 {(rels.typeDistribution || []).slice(0, 8).map((rt: any, i: number) => (
 <li key={i} className="csdm-rel-type-item">
 <span className="csdm-rel-type-name">{rt.type_name}</span>
 <span className="csdm-rel-type-count">{rt.count.toLocaleString()}</span>
 </li>
 ))}
 </ul>
 </>
 )}
 </div>
