import NodeDetail from './NodeDetail';
import DomainList from './DomainList';
import RiskPanel from './RiskPanel';
import RelationshipPanel from './RelationshipPanel';
import './Sidebar.css';

interface Props {
 data: any;
 selectedNode: any;
 activeView: string;
}

export default function Sidebar({ data, selectedNode, activeView }: Props) {
 function openTableView() {
 if (selectedNode && selectedNode.table) {
 // Navigate to the ServiceNow list view of the selected table
 const listUrl = `/now/nav/ui/classic/params/target/${selectedNode.table}_list.do`;
 window.open(listUrl, '_blank');
 }
 }

 return (
 <aside className="csdm-sidebar">
 {selectedNode && (
 <div className="csdm-sidebar__table-view-btn-wrapper">
 <button className="csdm-sidebar__table-view-btn" onClick={openTableView}>
 <span className="csdm-sidebar__table-view-icon">📋</span>
 Open Table View
 </button>
 <span className="csdm-sidebar__table-view-hint">
 Opens <strong>{selectedNode.table}</strong> list in a new tab
 </span>
 </div>
 )}
 {selectedNode && <NodeDetail node={selectedNode} />}
 {!selectedNode && activeView === 'overview' && <DomainList data={data} />}
 {!selectedNode && activeView === 'classes' && <DomainList data={data} detailed />}
 {!selectedNode && activeView === 'risks' && <RiskPanel data={data} />}
 {!selectedNode && activeView === 'relationships' && <RelationshipPanel data={data} />}
 {!selectedNode && !data && (
 <div className="csdm-sidebar__empty">
 <p>Click on a node in the 3D view to see details</p>
 </div>
 )}
 </aside>
 );
}
