 function getDimIcon(key: string) {
 const icons: Record<string, string> = {
 domain_coverage: '📊', data_completeness: '📝', service_model: '🔗',
 relationship_compliance: '↔️', lifecycle_governance: '🔄', data_hygiene: '🧹', customization_risk: '⚠️'
 };
 return icons[key] || '•';
 }

 return (
 <header className="csdm-header">
 <div className="csdm-header__title">
 <h1>CSDM 5.0 Explorer</h1>
 <span className="csdm-header__subtitle">Comprehensive Compliance Analysis</span>
 </div>

 <div className="csdm-header__metrics">
 <button className="csdm-trend-btn" onClick={() => window.open('/x_147805_csdmviz_trend.do', '_blank')} title="View CSDM score trends">
 📈 Trends
 </button>
 <div className={`csdm-metric csdm-metric--score ${getScoreColor(score)}`} onClick={() => setShowBreakdown(!showBreakdown)}>
 <span className="csdm-metric__value">{score}%</span>
 <span className="csdm-metric__label">CSDM Score ▾</span>
 </div>
 <div className="csdm-metric">
 <span className="csdm-metric__value">{population?.populatedClasses || 0}/{population?.totalClasses || 0}</span>
 <span className="csdm-metric__label">Classes</span>
 </div>
 <div className="csdm-metric csdm-metric--risk">
 <span className="csdm-metric__value">{risks?.total || 0}</span>
 <span className="csdm-metric__label">Risks</span>
 </div>
 {scanTime && (
 <div className="csdm-metric csdm-metric--time">
 <span className="csdm-metric__value csdm-metric__value--small">{scanTime}</span>
 <span className="csdm-metric__label">Scanned</span>
 </div>
 )}
 </div>

 <nav className="csdm-header__nav">
 {['overview', 'classes', 'risks', 'relationships'].map(view => (
 <button
 key={view}
 className={`csdm-nav-btn ${activeView === view ? 'csdm-nav-btn--active' : ''}`}
 onClick={() => onViewChange(view)}
 >
 {view.charAt(0).toUpperCase() + view.slice(1)}
 </button>
 ))}
 <button
 className={`csdm-scan-btn ${scanning ? 'csdm-scan-btn--scanning' : ''}`}
 onClick={onRefresh}
 disabled={scanning}
 >
 {scanning ? <><span className="csdm-scan-spinner" /> Scanning...</> : <>⚡ Scan Now</>}
 </button>
 </nav>

 {showBreakdown && dimensions && (
 <div className="csdm-score-breakdown">
 <div className="csdm-breakdown__title">Score Breakdown (7 Dimensions)</div>
 <div className="csdm-breakdown__grid">
 {Object.entries(dimensions).map(([key, dim]: [string, any]) => (
 <div key={key} className="csdm-breakdown__item">
 <div className="csdm-breakdown__header">
 <span className="csdm-breakdown__icon">{getDimIcon(key)}</span>
 <span className="csdm-breakdown__name">{dim.label}</span>
 <span className={`csdm-breakdown__score ${dim.score >= 70 ? 'good' : dim.score >= 40 ? 'warn' : 'bad'}`}>{dim.score}%</span>
 </div>
 <div className="csdm-breakdown__bar">
 <div className="csdm-breakdown__fill" style={{ width: `${dim.score}%`, background: dim.score >= 70 ? '#00e676' : dim.score >= 40 ? '#ffab00' : '#ff5252' }} />
 </div>
 <div className="csdm-breakdown__detail">{dim.detail}</div>
 <div className="csdm-breakdown__weight">Weight: {Math.round(dim.weight * 100)}%</div>
 </div>
 ))}
 </div>
 </div>
 )}
 </header>
 );
}
