","import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './app';

ReactDOM.createRoot(document.getElementById('root')!).render(<App />);
","import React, { useState, useEffect } from 'react';
import { fetchServerScan, fetchLatestScan } from './services/csdmApi';
import CSDMScene from './components/CSDMScene';
import Sidebar from './components/Sidebar';
import ScoreHeader from './components/ScoreHeader';
import './app.css';

export default function App() {
 const [data, setData] = useState<any>(null);
 const [loading, setLoading] = useState(true);
 const [scanning, setScanning] = useState(false);
 const [selectedNode, setSelectedNode] = useState<any>(null);
 const [activeView, setActiveView] = useState<string>('overview');
 useEffect(() => { loadCachedScan(); }, []);

 async function loadCachedScan() {
 setLoading(true);
 try {
 const cached = await fetchLatestScan();
 if (cached && cached.score !== undefined) {
 setData(cached);
 }
 } catch {
 // No cached data available — user will need to run a fresh scan
 }
 setLoading(false);
 }

 async function runFreshScan() {
 setScanning(true);
 try {
 const result = await fetchServerScan();
 if (result && result.score !== undefined) {
 setData(result);
 }
 } catch {
 // Keep previous data if scan fails
 }
 setScanning(false);
 }

 if (loading) {
 return (
 <div className="csdm-loading">
 <div className="csdm-loading-spinner" />
 <p>Loading CSDM compliance data...</p>
 <span className="csdm-loading-sub">Checking for cached scan results...</span>
 </div>
 );
 }

 if (!data) {
 return (
 <div className="csdm-loading">
 <p>No scan data available. Run a scan to analyze your CMDB.</p>
 <button className="csdm-retry-btn" onClick={runFreshScan} disabled={scanning}>
 {scanning ? 'Scanning...' : 'Run First Scan'}
 </button>
 </div>
 );
 }

 return (
 <div className="csdm-app">
 <ScoreHeader data={data} activeView={activeView} onViewChange={setActiveView} onRefresh={runFreshScan} scanning={scanning} />
 <div className="csdm-main">
 <CSDMScene data={data} onNodeSelect={setSelectedNode} activeView={activeView} />
 <Sidebar data={data} selectedNode={selectedNode} activeView={activeView} />
 </div>
 </div>
